Let $\Delta$ be a distribution on a manifold $B$. A \emph{partial $\Delta$-connection} in a vector bundle $\pi : E 	o B$ is given by a covariant derivative:  egin{equation*} 
abla : \Delta 	imes \Gamma(\pi)	o \Gamma(\pi) \end{equation*} such that  egin{equation}  egin{array}{l} 
abla_{\lambda X + Y} s = \lambda 
abla_X s + 
abla_Y s, \quad \lambda \in \mathcal{F}(B), X \in \mathfrak{X}(\Delta), s \in \Gamma(\pi); \ 
abla_{X} s_1 + s_2 = 
abla_X s_1 + 
abla_Y s_2; X \in \mathfrak{X}(\Delta), s_1, s_2 \in \Gamma(\pi); \ 
abla_{X} f s = Xf \, s + f 
abla_X s; \quad f \in \mathcal{F}(B), X \in \mathfrak{X}(\Delta), s \in \Gamma(\pi). \end{array} \end{equation}

Let $\left\{ e_\alpha ight\}$ be a local frame field of $\xi$, and $\omega = \omega^\alpha e_\alpha$. Then  egin{equation} 
abla_X (\omega(Y) ) = 
abla_X (\omega^\alpha(Y) e_\alpha ) = X(\omega^\alpha(Y)) e_\alpha + \omega^\alpha(Y) 
abla_X e_\alpha, \end{equation} therefore  egin{multline} 
abla_X (\omega(Y)) - 
abla_Y (\omega(X)) - \omega([X, Y]) = \ X(\omega^\alpha(Y)) e_\alpha + \omega^\alpha(Y) 
abla_X e_\alpha - Y(\omega^\alpha(X)) e_\alpha - \omega^\alpha(X) 
abla_Y e_\alpha - \omega^\alpha([X, Y]) e_\alpha = \ d\omega^\alpha(X, Y) e_\alpha - \omega^\alpha \wedge 
abla e_\alpha (X, Y) = D\omega (X, Y). \end{multline}

Let $\left\{ e_\alpha ight\}$ be a local frame field of $\xi$, and $\omega = \omega^\alpha e_\alpha$. Then  egin{equation} 
abla_X (\omega(Y) ) = 
abla_X (\omega^\alpha(Y) e_\alpha ) = X(\omega^\alpha(Y)) e_\alpha + \omega^\alpha(Y) 
abla_X e_\alpha, \end{equation}

therefore  egin{multline} 
abla_X (\omega(Y)) - 
abla_Y (\omega(X)) - \omega([X, Y]) = \ X(\omega^\alpha(Y)) e_\alpha + \omega^\alpha(Y) 
abla_X e_\alpha - Y(\omega^\alpha(X)) e_\alpha - \omega^\alpha(X) 
abla_Y e_\alpha - \omega^\alpha([X, Y]) e_\alpha = \ d\omega^\alpha(X, Y) e_\alpha - \omega^\alpha \wedge 
abla e_\alpha (X, Y) = D\omega (X, Y). \end{multline}
